import { useLayoutEffect, useEffect, useRef, useState } from 'react';
import gsap from 'gsap';
import { ScrollTrigger } from 'gsap/ScrollTrigger';
import { ScrollToPlugin } from 'gsap/ScrollToPlugin';

import './CarScrollBanner.css';

gsap.registerPlugin(ScrollTrigger, ScrollToPlugin);


const VIEWS = [
  { src: 'https://i.pinimg.com/736x/52/a6/f0/52a6f0b442ce950e4c4f4e87e2428597.jpg', label: 'FRONT 3/4', tag: ' 01  SIGNATURE POSE',    note: '4.0L V8 BITURBO + 3 ELECTRIC MOTORS' },
  { src: 'https://i.pinimg.com/1200x/fd/aa/35/fdaa351d5b2d4f2eb348d61989bc7796.jpg', label: 'AERO',      tag: ' 02  ACTIVE REAR WING',  note: 'GENERATED DOWNFORCE ON DEMAND' },
  { src: 'data:image/jpeg;base64,', label: 'DOORS UP',  tag: '03 — DIHEDRAL DOORS',    note: 'FRONT BOOT OPEN · ALUMINIUM FRAME' },              

  { src: 'https://i.pinimg.com/1200x/f8/13/7d/f8137ddd6b0ddaa805d650b302f41813.jpg', label: 'ENGINE',    tag: ' 04 REAR ENGINE BAY',   note: '780 CV COMBUSTION CORE' },
  { src: 'https://i.pinimg.com/736x/28/c1/f4/28c1f4997d94b4eadad4a349f5bf9ae7.jpg', label: 'FRONT',     tag: ' 05 FULL-LED MATRIX',   note: '1000 CV TOTAL OUTPUT' },
];

export default function CarScrollBanner() {
  const total   = VIEWS.length;
  const rootRef = useRef(null);
  const mediaRef  = useRef(null);
  const fillRef   = useRef(null);
  const idxRef    = useRef(null);
  const pctRef    = useRef(null);
  const hintRef   = useRef(null);
  const railRef   = useRef([]);
  const tlRef     = useRef(null);

  
  const [loadedCount, setLoadedCount] = useState(0);
  const ready = loadedCount >= total;

  const mark = (el) => {
    if (el && !el.dataset.ld) { el.dataset.ld = '1'; setLoadedCount(c => c + 1); }
  };


  useLayoutEffect(() => {
    if (!ready) return;

    const paint = () => {
      const views = rootRef.current?.querySelectorAll('.csw-view');
      if (!views) return;
      views.forEach((view, i) => {
        const h2 = view.querySelector('.csw-label');
        if (!h2 || !VIEWS[i].src) return;  
        const W = h2.offsetWidth;
        const H = h2.offsetHeight;
        h2.querySelectorAll('.ch').forEach(ch => {
          ch.style.backgroundImage    = `url("${VIEWS[i].src}")`;
          ch.style.backgroundSize     = `${W}px ${H}px`;
          ch.style.backgroundPosition = `${-ch.offsetLeft}px ${-ch.offsetTop}px`;
        });
      });
    };

    paint();
    document.fonts?.ready.then(paint);   
    const t = setTimeout(paint, 400);    
    let raf;
    const onResize = () => { cancelAnimationFrame(raf); raf = requestAnimationFrame(paint); };
    window.addEventListener('resize', onResize);
    return () => { clearTimeout(t); cancelAnimationFrame(raf); window.removeEventListener('resize', onResize); };
  }, [ready]);


  useLayoutEffect(() => {
    if (!ready) return;

    const ctx = gsap.context(() => {
      const root   = rootRef.current;
      const layers = gsap.utils.toArray('.csw-layer', root);
      const views  = gsap.utils.toArray('.csw-view',  root);
      const SEG    = 1.9; 

      gsap.from(views[0].querySelectorAll('.ch'), {
        yPercent: 120, opacity: 0, duration: .7, stagger: .045, ease: 'power3.out', delay: .25
      });
      gsap.from(views[0].querySelectorAll('.csw-fade'), {
        opacity: 0, y: 12, duration: .6, stagger: .1, delay: .55, ease: 'power2.out'
      });


      const tl = gsap.timeline({
        defaults: { ease: 'none' },
        scrollTrigger: {
          trigger: '.csw-stage',
          start: 'top top',
          end: `+=${(total - 1) * 1100}`,
          pin: true,
          scrub: 0.9,
          anticipatePin: 1,
          invalidateOnRefresh: true,
          onUpdate(self) {
            const p = self.progress;
            fillRef.current.style.transform = `scaleX(${p})`;
            pctRef.current.textContent = String(Math.round(p * 100)).padStart(2, '0') + '%';
            const i = Math.round(p * (total - 1));
            idxRef.current.textContent = String(i + 1).padStart(2, '0');
            hintRef.current.classList.toggle('off', p > 0.03);
            railRef.current.forEach((el, j) => el && el.classList.toggle('on', j === i));
          }
        }
      });
      tlRef.current = tl;

    
      for (let i = 1; i < total; i++) {
        const at = (i - 1) * SEG;

        tl.to(layers[i],     { opacity: 1, duration: 1, ease: 'power1.inOut' }, at)
          .to(layers[i - 1], { opacity: 0, duration: 1, ease: 'power1.inOut' }, at)
          .fromTo(layers[i].querySelector('img, .csw-ph'),
            { scale: 1.16 },
            { scale: 1, duration: 1.5, ease: 'power2.out' }, at)
          .to(views[i - 1], { autoAlpha: 0, y: -26, duration: .4, ease: 'power1.in' }, at)
          .fromTo(views[i], { autoAlpha: 0, y: 26 }, { autoAlpha: 1, y: 0, duration: .01 }, at + .5)
          .fromTo(views[i].querySelectorAll('.ch'),
            { yPercent: 120, opacity: 0 },
            { yPercent: 0, opacity: 1, duration: .5, stagger: .035, ease: 'power3.out' }, at + .52)
          .fromTo(views[i].querySelectorAll('.csw-fade'),
            { opacity: 0, y: 14 },
            { opacity: 1, y: 0, duration: .4, stagger: .08, ease: 'power2.out' }, at + .75);
      }

   
      gsap.from('.csw-outro > *', {
        scrollTrigger: { trigger: '.csw-outro', start: 'top 78%' },
        y: 36, opacity: 0, stagger: .1, duration: .8, ease: 'power3.out'
      });
    }, rootRef);

    return () => ctx.revert();
  }, [ready, total]);

  /* ---- mouse parallax ---- */
  // useEffect(() => {
  //   if (!ready) return;
  //   if (matchMedia('(prefers-reduced-motion: reduce)').matches) return;
  //   const el  = mediaRef.current;
  //   const xTo = gsap.quickTo(el, 'x', { duration: .8, ease: 'power3' });
  //   const yTo = gsap.quickTo(el, 'y', { duration: .8, ease: 'power3' });
  //   const move = e => {
  //     xTo((e.clientX / innerWidth  - .5) * -24);
  //     yTo((e.clientY / innerHeight - .5) * -16);
  //   };
  //   addEventListener('pointermove', move);
  //   return () => removeEventListener('pointermove', move);
  // }, [ready]);


  const jump = (i) => {
    const st = tlRef.current?.scrollTrigger;
    if (!st) return;
    gsap.to(window, {
      scrollTo: st.start + (i / (total - 1)) * (st.end - st.start) + 2,
      duration: 1.2, ease: 'power2.inOut'
    });
  };

  return (
    <div className="csw" ref={rootRef}>
      <header className="csw-top">
        <div className="csw-brand">SF90<em>.</em></div>
        <div className="csw-meta">HYBRID V8 — 1000 CV · SCROLL SHOWCASE</div>
      </header>


      <section className="csw-stage">
        <div className="csw-media" ref={mediaRef}>
          {VIEWS.map((v, i) => (
            <div className="csw-layer" key={i}>
              {v.src
                ? <img src={v.src} alt={v.label} ref={mark} onLoad={e => mark(e.target)} />
                : <div className="csw-ph" ref={mark} />}
            </div>
          ))}
        </div>

        <div className="csw-vignette" />

        <div className="csw-copy">
          {VIEWS.map((v, i) => (
            <div className="csw-view" key={i}>
              <p className="csw-tag csw-fade">{v.tag}</p>
              <h2 className={`csw-label ${v.src ? '' : 'no-img'}`} aria-label={v.label}>
                {v.label.split('').map((c, j) => (
                  <span className="ch" key={j}>{c === ' ' ? '\u00A0' : c}</span>
                ))}
              </h2>
              <p className="csw-note csw-fade">{v.note}</p>
            </div>
          ))}
        </div>

        <div className="csw-hud">
          <div className="csw-idx"><b ref={idxRef}>01</b> / {String(total).padStart(2, '0')}</div>

          <div className="csw-rail">
            {VIEWS.map((v, i) => (
              <button key={i} className={i === 0 ? 'on' : ''}
                      ref={el => (railRef.current[i] = el)}
                      onClick={() => jump(i)}>
                <span className="rn">{String(i + 1).padStart(2, '0')} {v.label}</span>
                <i className="n" />
              </button>
            ))}
          </div>

          <div className="csw-hint" ref={hintRef}>SCROLL <span className="pulse" /></div>
          <div className="csw-pct" ref={pctRef}>0%</div>
          <div className="csw-progress"><div ref={fillRef} /></div>
        </div>
      </section>

   

   
      <div className={`csw-loader ${ready ? 'done' : ''}`}>
        <div>
          <p className="lt">LOADING SEQUENCE</p>
          <div className="lb"><div style={{ width: `${(loadedCount / total) * 100}%` }} /></div>
          <p className="lp">{Math.round((loadedCount / total) * 100)}%</p>
        </div>
      </div>

      <div className="csw-grain" />
    </div>
  );
}